<form class="settings-card-form narrow" method="post"><h2>Payment Settings</h2><input type="hidden" name="csrf" value="<?=sh($_SESSION['csrf'])?>"><p class="helper-text">Set how many payments can be recorded for one confirmed booking.</p><label>Maximum payments per booking<select name="max_payment_steps"><?php for($i=1;$i<=5;$i++):?><option <?=$i==(int)($s['max_payment_steps']??5)?'selected':''?>><?=$i?></option><?php endfor;?></select></label><fieldset><legend>Payment Methods</legend><p class="helper-text">Only checked methods will appear when recording a payment.</p><?php foreach(['cash'=>'Cash','bank-transfer'=>'Bank Transfer','upi'=>'UPI','cheque'=>'Cheque','card'=>'Card','other'=>'Other'] as $value=>$label):?><label class="toggle"><input type="checkbox" name="payment_methods[]" value="<?=sh($value)?>" <?=in_array($value,$methods,true)?'checked':''?>><span><?=sh($label)?></span></label><?php endforeach;?></fieldset><div class="single-admin"><strong>Tell the guest about the payment plan</strong><p>Payment terms are not sent automatically. Explain the agreed schedule to the guest before recording payments.</p></div><button class="primary-button" name="action" value="save_payments">Save Payment Settings</button></form>
